entries[121411] = { ["name"] = "Blutroter Sturm", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der alle Combopunkte eines nahen Ziels verbraucht, um tief in das Fleisch von Gegnern im Umkreis von 8 Metern zu schneiden. Verursacht körperlichen Schaden und lässt Ziele bluten, wodurch sie im Verlauf von 12 Sek. zusätzlich 240% des Initialschadens erleiden:\n1 Punkt: [(( 297 + 889 ) / 2) + 5 + ((Angriffskraft * 0.0275) * 1 )]) Schaden\n2 Punkte: [(( 297 + 889 ) / 2) + (10) + ((Angriffskraft * 0.055) * 1 )]) Schaden\n3 Punkte: [(( 297 + 889 ) / 2) + (15) + ((Angriffskraft * 0.0825) * 1 )]) Schaden\n4 Punkte: [(( 297 + 889 ) / 2) + (20) + ((Angriffskraft * 0.11) * 1 )]) Schaden\n5 Punkte: [(( 297 + 889 ) / 2) + (25) + ((Angriffskraft * 0.1375) * 1 )]) Schaden" }
entries[121414] = { ["name"] = "Glevenwurf", ["text"] = "Sofort\nIhr schleudert zwei Gleven in Richtung eines Ziels. Jede Gleve fügt jedem getroffenen Gegner 873 Schaden zu und verringert sein Bewegungstempo 3 Sek. lang um 30%. Das Primärziel erleidet für jedes getroffene Ziel den 4-fachen Schaden.\n\nDie Gleven kehren zu Euch zurück und verursachen auf ihrem Rückweg ebenfalls Schaden und verlangsamen Gegner." }
