entries[121841] = { ["name"] = "Rubinpanther", ["text"] = "Wirken in 10 sek. 5\nTools: Juweliersset\nReagenzien:\nKugel der Geheimnisse , Rubellit (20), Lebendiger Stahl (4), Serpentin (2)\nRubinpanther\nReittier\n40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier fliegt oder läuft in Abhängigkeit von Eurer Reitfertigkeit und Eurem Aufenthaltsort.\nBeschwört einen reitbaren Rubinpanther oder gibt ihn wieder frei." }
entries[121842] = { ["name"] = "Saphirpanther", ["text"] = "Wirken in 10 sek. 5\nTools: Juweliersset\nReagenzien:\nKugel der Geheimnisse , Chrysokoll (20), Lebendiger Stahl (4), Serpentin (2)\nSaphirpanther\nReittier\n40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier fliegt oder läuft in Abhängigkeit von Eurer Reitfertigkeit und Eurem Aufenthaltsort.\nBeschwört einen reitbaren Saphirpanther oder gibt ihn wieder frei." }
entries[121843] = { ["name"] = "Sonnensteinpanther", ["text"] = "Wirken in 10 sek. 5\nTools: Juweliersset\nReagenzien:\nKugel der Geheimnisse , Goldberyll (20), Lebendiger Stahl (4), Serpentin (2)\nSonnensteinpanther\nReittier\n40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier fliegt oder läuft in Abhängigkeit von Eurer Reitfertigkeit und Eurem Aufenthaltsort.\nBeschwört einen reitbaren Sonnensteinpanther oder gibt ihn wieder frei." }
entries[121844] = { ["name"] = "Jadepanther", ["text"] = "Wirken in 10 sek. 5\nTools: Juweliersset\nReagenzien:\nKugel der Geheimnisse , Dioptas (20), Lebendiger Stahl (4), Serpentin (2)\nJadepanther\nReittier\n40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier fliegt oder läuft in Abhängigkeit von Eurer Reitfertigkeit und Eurem Aufenthaltsort.\nBeschwört einen reitbaren Jadepanther oder gibt ihn wieder frei." }
