entries[122278] = { ["name"] = "Schaden dämpfen", ["text"] = "Sofort 1.5 min Abklingzeit\nIhr schwächt den eintreffenden Schaden der stärksten Angriffe ab. Die nächsten 3 Angriffe innerhalb von 45 Sek., die mindestens Schaden in Höhe von 20% Eurer Maximalgesundheit verursachen würden, verursachen nur die Hälfte des Schadens.\n\nDiese Fähigkeit kann eingesetzt werden, während Ihr betäubt seid." }
entries[122280] = { ["name"] = "Heilende Elixiere", ["text"] = "Alle 18 Sek. erhaltet Ihr den Effekt 'Heilende Elixiere'.\n\nDieser Effekt heilt Euch das nächste Mal, wenn ein Angriff Eure Gesundheit unter 35% fallen lässt oder Ihr ein Gebräu oder einen Tee verbraucht, um 15% Eurer maximalen Gesundheit." }
entries[122281] = { ["name"] = "Heilende Elixiere", ["text"] = "Sofort\nAlle 18 Sek. erhaltet Ihr den Effekt 'Heilende Elixiere'.\n\nDieser Effekt heilt Euch das nächste Mal, wenn ein Angriff Eure Gesundheit unter 35% fallen lässt oder Ihr ein Gebräu oder einen Tee verbraucht, um 15% Eurer maximalen Gesundheit." }
