entries[122285] = { ["name"] = "Knochenschild", ["text"] = "Sofort 1 min Abklingzeit\nUmgibt Euch mit einer Barriere aus wirbelnden Knochen. Der Schild hat anfänglich 3 Aufladungen, jeder Schaden verursachende Angriff verbraucht jedoch eine Aufladung. Solang zumindest 1 Aufladung verbleibt, wird jeglicher von Euch erlittene Schaden um 10% verringert. Hält 5 Min. lang an.\n(2s Abklingzeit)" }
entries[122286] = { ["name"] = "Wilde Verteidigung", ["text"] = "60 WutSpontanzauber 1 min Abklingzeit\nSymbiose: Erhöht die Ausweichchance um 30%. Hält 6 Sek. lang an." }
entries[122287] = { ["name"] = "Zorn", ["text"] = "1.7% von Grundmana 40 Meter Reichweite\nWirken in 2 sek.\nSymbiose: Fügt dem Ziel 13794 Naturschaden zu." }
entries[122288] = { ["name"] = "Läuterung", ["text"] = "16.4% von Grundmana 40 Meter Reichweite\nSofort 8 sek. Abklingzeit\nReinigt ein verbündetes Ziel und hebt dabei sämtliche Gift- und Krankheitseffekte auf." }
entries[122289] = { ["name"] = "Finte", ["text"] = "20 Wut / 10 Energie\nSpontanzauber\nBenötigt Katzengestalt, Bärengestalt\nFührt ein Ausweichmanöver durch, das 5 Sek. lang Euren durch Flächeneffekte erlittenen Schaden um 10% verringert." }
entries[122290] = { ["name"] = "Aderlass", ["text"] = "Sofort 15 sek. Abklingzeit\nBenötigt Bärengestalt\nWandelt 20% Eurer Gesamtgesundheit in 30 Wut um." }
entries[122291] = { ["name"] = "Erbarmungslose Entschlossenheit", ["text"] = "10% von Grundmana\nSofort 3 min Abklingzeit\nDie Haut des Druiden verhärtet sich, was jeglichen erlittenen Schaden um 40% verringert und verhindert, dass das Wirken Zaubern unterbrochen wird. Hält 12 Sek. lang an." }
entries[122292] = { ["name"] = "Einschreiten", ["text"] = "25 Meter Reichweite\nSofort 30 sek. Abklingzeit\nLauft mit hoher Geschwindigkeit auf ein Gruppen- oder Schlachtzugsmitglied zu, um den nächsten Nahkampf- oder Distanzangriff innerhalb von 10 Sek. gegen dieses Ziel abzufangen, während es sich innerhalb von 10 Metern befindet." }
entries[122293] = { ["name"] = "Große Unsichtbarkeit", ["text"] = "Sofort\nMacht den Zaubernden sofort unsichtbar, verringert jegliche Bedrohung und entfernt zwei Effekte, die regelmäßigen Schaden verursachen. Während Ihr unsichtbar seid, können Feinde Euch nicht anvisieren. Hält 20 Sek. lang an. [ Glyphe 'Unsichtbarkeit' : Während Ihr unsichtbar seid, wird Euer Bewegungstempo um 40% erhöht ] Der Effekt wird abgebrochen, wenn Ihr Aktionen ausführt.\n\nWährend Ihr unsichtbar seid und 3 Sek. lang nach Ende dieses Effekts ist der von Euch erlittene Schaden um 90% verringert.\n\nErsetzt 'Unsichtbarkeit'." }
entries[122294] = { ["name"] = "Anstachelnder Ruf", ["text"] = "Sofort 5 min Abklingzeit\nSymbiose: Der Krieger stößt einen Schrei aus, der 8 Sek. lang das Bewegungstempo aller verbündeten Spielercharaktere im Umkreis von 10 Metern um 60% erhöht, zudem werden alle bewegungseinschränkenden Effekte entfernt." }
