entries[122752] = { ["name"] = "Schattenodem", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerursacht 409500 bis 430500 Schattenschaden und erhöht erlittenen Schattenschaden 30 Sek. lang um 100%. Stapelbar." }
