entries[122754] = { ["name"] = "Furor", ["text"] = "Wirken in 1.5 sek.\nWenn Galaron mindestens 2 Ziele verfehlt, wird er wütend, sodass 15 Sek. lang sein verursachter Schaden um 10% und sein Bewegungstempo um 10% erhöht ist. Stapelbar." }
