entries[122761] = { ["name"] = "Ausatmen", ["text"] = "60 Meter Reichweite\nWirken in 2 sek. 5 sek. Abklingzeit\nDer kaiserliche Wesir Zor'lok schreit einen zufälligen Spielercharakter 6 Sek. lang an. Der erste Spielercharakter zwischen dem Zaubernden und dem Ziel absorbiert den Großteil dieses Angriffs. 'Ausatmen' fügt dem Opfer körperlichen Schaden zu[und betäubt das ursprüngliche Ziel des Zaubers.][.]" }
