entries[122782] = { ["name"] = "Sonnenstrahl", ["text"] = "Sofort\nIm Sonnenstrahl zu stehen, macht das Ziel gegen 'Schreckensschatten' immun, lässt den Sonnenstrahl allerdings langsam schrumpfen." }
entries[122783] = { ["name"] = "Magiediffusion", ["text"] = "Sofort 1.5 min Abklingzeit\nVerringert sämtlichen erlittenen Zauberschaden um 90%, bannt sämtliche magischen Effekte, die auf Euch wirken, und schickt sie zu ihrem Verursacher zurück, wenn er nicht weiter als 40 Meter von Euch entfernt ist. Hält 6 Sek. lang an." }
